{"content": "package com.example.controller;

import com.example.dao.UserDAO;
import com.example.model.User;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;

/**
 * 用户控制器 - 处理所有用户相关的请求
 */
@WebServlet(name = "UserServlet", urlPatterns = {"/user", "/user/list", "/user/add", "/user/edit", "/user/delete", "/user/search"})
public class UserServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    private UserDAO userDAO;

    @Override
    public void init() throws ServletException {
        userDAO = new UserDAO();
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        String action = request.getServletPath();
        String viewPath = "/WEB-INF/jsp/";

        try {
            switch (action) {
                case "/user/delete":
                    doDelete(request, response);
                    break;
                case "/user/edit":
                    showEditForm(request, response, viewPath);
                    break;
                case "/user/add":
                    showAddForm(request, response, viewPath);
                    break;
                case "/user/search":
                    doSearch(request, response, viewPath);
                    break;
                case "/user/list":
                case "/user":
                default:
                    listUsers(request, response, viewPath);
                    break;
            }
        } catch (Exception e) {
            handleException(request, response, e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        String action = request.getServletPath();

        try {
            if ("/user/add".equals(action)) {
                doAdd(request, response);
            } else if ("/user/edit".equals(action)) {
                doUpdate(request, response);
            } else {
                // 其他POST请求当作列表处理
                response.sendRedirect(request.getContextPath() + "/user/list");
            }
        } catch (Exception e) {
            handleException(request, response, e);
        }
    }

    /**
     * 显示用户列表
     */
    private void listUsers(HttpServletRequest request, HttpServletResponse response, String viewPath) 
            throws ServletException, IOException {
        List<User> users = userDAO.findAll();
        request.setAttribute("users", users);
        request.getRequestDispatcher(viewPath + "user-list.jsp").forward(request, response);
    }

    /**
     * 显示新增表单
     */
    private void showAddForm(HttpServletRequest request, HttpServletResponse response, String viewPath) 
            throws ServletException, IOException {
        request.getRequestDispatcher(viewPath + "user-form.jsp").forward(request, response);
    }

    /**
     * 显示编辑表单
     */
    private void showEditForm(HttpServletRequest request, HttpServletResponse response, String viewPath) 
            throws ServletException, IOException {
        Integer id = parseId(request.getParameter("id"));
        if (id == null) {
            response.sendRedirect(request.getContextPath() + "/user/list");
            return;
        }

        User user = userDAO.findById(id);
        if (user == null) {
            response.sendRedirect(request.getContextPath() + "/user/list");
            return;
        }

        request.setAttribute("user", user);
        request.setAttribute("isEdit", true);
        request.getRequestDispatcher(viewPath + "user-form.jsp").forward(request, response);
    }

    /**
     * 处理新增
     */
    private void doAdd(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        User user = extractUserFromRequest(request);

        // 检查用户名是否已存在
        if (userDAO.findByUsername(user.getUsername()) != null) {
            request.setAttribute("error", "用户名已存在");
            request.setAttribute("user", user);
            request.getRequestDispatcher("/WEB-INF/jsp/user-form.jsp").forward(request, response);
            return;
        }

        if (userDAO.insert(user)) {
            response.sendRedirect(request.getContextPath() + "/user/list");
        } else {
            request.setAttribute("error", "添加用户失败");
            request.getRequestDispatcher("/WEB-INF/jsp/user-form.jsp").forward(request, response);
        }
    }

    /**
     * 处理更新
     */
    private void doUpdate(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        Integer id = parseId(request.getParameter("id"));
        if (id == null) {
            response.sendRedirect(request.getContextPath() + "/user/list");
            return;
        }

        User user = extractUserFromRequest(request);
        user.setId(id);

        // 检查用户名是否已被其他用户使用
        User existingUser = userDAO.findByUsername(user.getUsername());
        if (existingUser != null && !existingUser.getId().equals(id)) {
            request.setAttribute("error", "用户名已被其他用户使用");
            request.setAttribute("user", user);
            request.setAttribute("isEdit", true);
            request.getRequestDispatcher("/WEB-INF/jsp/user-form.jsp").forward(request, response);
            return;
        }

        if (userDAO.update(user)) {
            response.sendRedirect(request.getContextPath() + "/user/list");
        } else {
            request.setAttribute("error", "更新用户失败");
            request.setAttribute("user", user);
            request.setAttribute("isEdit", true);
            request.getRequestDispatcher("/WEB-INF/jsp/user-form.jsp").forward(request, response);
        }
    }

    /**
     * 处理删除
     */
    private void doDelete(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        Integer id = parseId(request.getParameter("id"));
        if (id != null) {
            userDAO.delete(id);
        }
        response.sendRedirect(request.getContextPath() + "/user/list");
    }

    /**
     * 处理搜索
     */
    private void doSearch(HttpServletRequest request, HttpServletResponse response, String viewPath) 
            throws ServletException, IOException {
        String keyword = request.getParameter("keyword");
        List<User> users;

        if (keyword != null && !keyword.trim().isEmpty()) {
            users = userDAO.searchByUsername(keyword.trim());
            request.setAttribute("keyword", keyword);
        } else {
            users = userDAO.findAll();
        }

        request.setAttribute("users", users);
        request.getRequestDispatcher(viewPath + "user-list.jsp").forward(request, response);
    }

    /**
     * 异常处理
     */
    private void handleException(HttpServletRequest request, HttpServletResponse response, Exception e) 
            throws ServletException, IOException {
        e.printStackTrace();
        request.setAttribute("error", "系统错误: " + e.getMessage());
        request.getRequestDispatcher("/WEB-INF/jsp/user-list.jsp").forward(request, response);
    }

    /**
     * 从请求中提取用户对象
     */
    private User extractUserFromRequest(HttpServletRequest request) {
        User user = new User();
        user.setUsername(request.getParameter("username"));
        user.setPassword(request.getParameter("password"));
        user.setEmail(request.getParameter("email"));
        user.setPhone(request.getParameter("phone"));
        return user;
    }

    /**
     * 解析ID参数
     */
    private Integer parseId(String idStr) {
        if (idStr == null || idStr.trim().isEmpty()) {
            return null;
        }
        try {
            return Integer.parseInt(idStr);
        } catch (NumberFormatException e) {
            return null;
        }
    }
